{
  "story": "How does a robot arm pick up an object? Start with the object resting on a table. Advance through approach, grasp, and lift; watch what supports the object. Assume a rigid object, known position, sufficient grip, and a clear path. Use Previous and Next; every state waits for you.",
  "aha": {
    "stateId": "lift",
    "observation": "Once the gripper secures the object, raising the robot arm carries the object off the table."
  },
  "layout": {
    "preset": "stepper-states",
    "width": 640
  },
  "parts": [
    {
      "id": "pickup-rail",
      "kind": "step-rail",
      "presentation": "Place below the explanation and above the experiment. Show the active state and completed trace here, without implying elapsed time. Brief parameter-control budget: zero; Previous, Next, and Reset are navigation controls.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "pickup-picture",
      "kind": "fixed-picture",
      "presentation": "Use one changing scene region within the approved fixed-picture layout. Select its phase by matching variant.states order. Keep the camera, table reference, and diagram scale fixed. Label Robot arm, Gripper, Object, and Table throughout. Reference capture shows the Lift aha state.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "pickup-callout",
      "kind": "active-callout",
      "presentation": "Anchor beside the gripper within the targeted scene region. Reserve label space in every state; identify the active relationship without repeating readout values.",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "pickup-status",
      "kind": "value-readout",
      "presentation": "Show one bound status line beneath the picture, reporting what currently supports the object. These categorical values require no units or rounding.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "step",
      "kind": "index",
      "items": "variant.states",
      "label": "Pickup step",
      "presentation": "Use Previous and Next buttons. Default: first state; bounds: first through last state; increment: one state. Retain button names when disabled at boundaries. Each state persists until learner action, including Lift. Provide keyboard operation, accessible names, and visible focus."
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset",
      "presentation": "Restore the first state and all defaults. Provide keyboard operation, an accessible name, and visible focus."
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Known-position object pickup",
        "regions": [
          {
            "id": "pickup-scene",
            "label": "Robot arm, Gripper, Object, and Table",
            "phases": [
              "Robot arm above the table; gripper open above the object; object resting on the stationary table.",
              "Robot arm lowered; gripper open around the object; object still resting on the stationary table.",
              "Robot arm stationary; gripper closed around the object; object still resting on the stationary table.",
              "Robot arm raised; gripper closed around the object; object held above the stationary table, with a visible gap beneath it."
            ]
          }
        ],
        "links": [],
        "states": [
          {
            "id": "ready",
            "label": "Ready",
            "short": "Locate",
            "sentence": "Gripper above the object.",
            "why": "The known object position tells the robot arm where to place its open gripper.",
            "active": [
              "pickup-scene"
            ],
            "calloutRegion": "pickup-scene",
            "readouts": [
              {
                "id": "support",
                "label": "Object support",
                "value": "Table"
              }
            ]
          },
          {
            "id": "approach",
            "label": "Approach",
            "short": "Approach",
            "sentence": "Open gripper around the object.",
            "why": "The robot arm places the gripper on opposite sides without moving the object.",
            "active": [
              "pickup-scene"
            ],
            "calloutRegion": "pickup-scene",
            "readouts": [
              {
                "id": "support",
                "label": "Object support",
                "value": "Table"
              }
            ]
          },
          {
            "id": "grasp",
            "label": "Grasp",
            "short": "Grasp",
            "sentence": "Gripper touching both sides of the object.",
            "why": "Closing the gripper secures the object before the robot arm lifts.",
            "active": [
              "pickup-scene"
            ],
            "calloutRegion": "pickup-scene",
            "readouts": [
              {
                "id": "support",
                "label": "Object support",
                "value": "Table"
              }
            ]
          },
          {
            "id": "lift",
            "label": "Lift",
            "short": "Lift",
            "sentence": "Object inside the raised gripper.",
            "why": "The gap above the table shows that the secured object moved with the robot arm.",
            "active": [
              "pickup-scene"
            ],
            "calloutRegion": "pickup-scene",
            "readouts": [
              {
                "id": "support",
                "label": "Object support",
                "value": "Gripper"
              }
            ]
          }
        ]
      }
    ]
  }
}
